    "explicacaoComoSeTivesse12": "Imagine como aprender as regras de um jogo sério: primeiro você entende quem pode agir, quando pode agir e qual consequência acontece. Neste capítulo, \"Ação penal: espécies e condições\", a ideia principal é: Ação penal é o instrumento pelo qual se provoca o Poder Judiciário a julgar uma pretensão punitiva. Para estudar sem travar, guarde primeiro estas palavras-chave: ação penal pública, ação penal privada, representação. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Regra geral é ação pública incondicionada; condicionada exige representação/requisição; privada é conduzida pela vítima via queixa.",
