    "corpo": [
      "Competência é a medida da jurisdição — define qual juízo específico deve julgar determinado caso. A regra geral de competência territorial no processo penal brasileiro é o lugar da consumação do crime (teoria do resultado), diferente do Direito Penal material, que adota a teoria da ubiquidade para fins de aplicação da lei no espaço.",
      "Além da competência territorial, existe a competência material (definida pela natureza do crime — ex.: crimes militares vão para a Justiça Militar, crimes eleitorais para a Justiça Eleitoral) e a competência funcional (definida pela fase do processo ou pela função exercida — ex.: o juiz que pronuncia não necessariamente é o que preside o julgamento no júri).",
      "Conexão e continência são institutos que reúnem processos distintos para julgamento conjunto, evitando decisões contraditórias. Conexão ocorre quando há vínculo entre crimes (praticados em concurso, para facilitar ou ocultar outro, ou quando a prova de um influencia a prova de outro). Continência ocorre quando duas ou mais pessoas são acusadas pela mesma infração (concurso de agentes) ou quando há concurso formal de crimes."
    ],
    "pontosChave": [
      "Competência territorial no processo penal: regra geral é o lugar da consumação do crime.",
      "Competência material considera a natureza do crime (militar, eleitoral, comum); competência funcional considera a fase/função no processo.",
      "Conexão une crimes vinculados; continência une pessoas (concurso de agentes) ou crimes em concurso formal."
    ],
    "checkRapido": {
      "pergunta": "Duas pessoas cometem, em concurso de agentes, um furto em uma cidade. Qual instituto justifica que ambas sejam julgadas no mesmo processo?",
      "opcoes": [
        "Conexão",
        "Continência",
        "Prevenção"
      ],
      "correta": 1,
      "justificativa": "Continência é o instituto aplicável quando duas ou mais pessoas são acusadas pela mesma infração penal (concurso de agentes) — nesse caso, ambas devem, em regra, ser processadas e julgadas conjuntamente."
    },
    "oQueCobra": "Aplicar os critérios de fixação de competência (territorial, material, funcional) e diferenciar conexão de continência.",
    "precisaSaberAntes": "Reconhecer a estrutura do Poder Judiciário (Justiça Comum, Militar, Eleitoral, Federal) para aplicar a competência material.",
    "explicacao": [
      {
        "titulo": "Prevenção como critério subsidiário",
        "texto": "Quando dois ou mais juízos são igualmente competentes segundo os critérios anteriores, a competência se firma pela prevenção: o juízo que primeiro conheceu do caso (praticou algum ato decisório) fica prevento para julgá-lo."
      },
      {
        "titulo": "Separação obrigatória de processos",
        "texto": "Mesmo havendo conexão ou continência, a lei determina separação obrigatória em certos casos: no concurso entre a Justiça comum e o Tribunal do Júri (crimes conexos que não sejam dolosos contra a vida são separados, salvo exceções), e quando um dos acusados é inimputável por doença mental (o processo dele segue separado, com aplicação de medida de segurança, se cabível)."
      }
    ],
    "comoIdentificar": "Casos com múltiplos réus ou múltiplos crimes interligados testam se a situação é de conexão, continência, ou separação obrigatória.",
    "pegadinhas": [
      "Confundir conexão (vínculo entre crimes) com continência (vínculo entre pessoas/concurso formal).",
      "Não aplicar a separação obrigatória quando há coexistência entre crime doloso contra a vida (júri) e outros crimes conexos, em situações que a lei determina separação.",
      "Ignorar a prevenção como critério de desempate quando dois juízos são igualmente competentes."
    ],
    "resumoFrase": "Conexão une crimes vinculados; continência une pessoas ou concurso formal — na dúvida entre juízos igualmente competentes, decide a prevenção.",
