    "title": "Provas: princípios gerais e prova ilícita",
    "assunto": "Teoria geral da prova",
    "tecnica": "Distinção entre prova ilícita e ilegítima, e aplicação da teoria dos frutos da árvore envenenada",
    "competencia": "Reconhecer os princípios da prova e as consequências de sua obtenção ilícita",
    "dificuldade": "Difícil",
