    "termosChave": [
      "prova ilícita",
      "cadeia de custódia",
      "fruto da árvore envenenada"
    ],
    "corpo": [
      "Prova é todo elemento capaz de formar a convicção do julgador sobre a existência de um fato. A Constituição veda expressamente as provas obtidas por meios ilícitos, e o Código de Processo Penal determina que sejam desentranhadas do processo, isto é, retiradas fisicamente dos autos.",
      "Prova ilícita é a obtida com violação a norma de direito material (ex.: interceptação telefônica sem autorização judicial, confissão obtida mediante tortura). Prova ilegítima é a obtida com violação a norma de direito processual (ex.: juntada de documento fora do prazo legal, sem observar o rito previsto). A distinção importa porque as consequências processuais podem ser tratadas com nuances diferentes pela doutrina, embora ambas sejam, em regra, inadmissíveis.",
      "A teoria dos frutos da árvore envenenada (fruits of the poisonous tree) estabelece que as provas derivadas de uma prova ilícita também são contaminadas e devem ser excluídas do processo — salvo se demonstrado que seriam obtidas por uma fonte independente, ou que a descoberta seria inevitável por outros meios legítimos já em curso."
    ],
    "pontosChave": [
      "Prova ilícita viola norma de direito material; prova ilegítima viola norma de direito processual.",
      "Provas ilícitas devem ser desentranhadas do processo — não podem fundamentar a decisão.",
      "Teoria dos frutos da árvore envenenada: provas derivadas de prova ilícita também são contaminadas, salvo fonte independente ou descoberta inevitável."
    ],
    "checkRapido": {
      "pergunta": "A polícia obtém uma confissão mediante coação física do investigado, e a partir dela localiza uma arma usada no crime. A prova da localização da arma é:",
      "opcoes": [
        "Válida, pois a arma em si não foi obtida ilicitamente",
        "Contaminada, pela teoria dos frutos da árvore envenenada, salvo se comprovada fonte independente",
        "Sempre válida, pois provas materiais nunca são excluídas"
      ],
      "correta": 1,
      "justificativa": "Como a localização da arma decorreu diretamente da confissão obtida por meio ilícito (coação), ela é considerada fruto da árvore envenenada e, em regra, também deve ser excluída — a menos que se demonstre que a arma seria descoberta de qualquer forma, por uma fonte de investigação totalmente independente da confissão viciada."
    },
    "oQueCobra": "Reconhecer prova ilícita e ilegítima, e aplicar a teoria dos frutos da árvore envenenada e suas exceções.",
    "precisaSaberAntes": "Entender a diferença entre norma de direito material (penal) e norma de direito processual.",
    "explicacao": [
      {
        "titulo": "Exceções à contaminação da prova derivada",
        "texto": "Fonte independente: a prova derivada seria obtida de qualquer forma, por linha de investigação totalmente distinta da prova ilícita. Descoberta inevitável: mesmo sem a prova ilícita, as circunstâncias indicavam que a prova derivada seria descoberta por meios regulares já em andamento."
      },
      {
        "titulo": "Cadeia de custódia",
        "texto": "É o conjunto de procedimentos que garantem a rastreabilidade e a integridade de uma prova, desde sua coleta no local do crime até seu uso em juízo — qualquer quebra na cadeia de custódia (manuseio inadequado, ausência de documentação da coleta) pode gerar questionamento sobre a idoneidade da prova, mesmo que ela não tenha sido obtida de forma ilícita em sua origem."
      }
    ],
    "comoIdentificar": "Casos com sequência de provas obtidas a partir de uma prova questionável testam a teoria dos frutos da árvore envenenada e suas exceções.",
