    "title": "Audiência de custódia e liberdade provisória",
    "assunto": "Controle judicial da prisão",
    "tecnica": "Sequência de decisões possíveis após a apresentação do preso",
    "competencia": "Reconhecer a finalidade da audiência de custódia e as modalidades de liberdade provisória",
    "dificuldade": "Média",
    "tempoLeituraMin": 7,
