        "texto": "Gratuito, pode ser impetrado por qualquer pessoa em favor de outra (não exige capacidade postulatória, isto é, não precisa ser advogado), e serve tanto de forma preventiva (salvo-conduto, quando há apenas ameaça à liberdade) quanto repressiva (liberatório, quando a coação ilegal já se consumou)."
